<script setup>
import {ref,onMounted} from 'vue';import {supabase} from '../lib/supabase.js'
const rows=ref([]),loading=ref(true),saving=ref(''),error=ref(''),success=ref('')
async function load(){loading.value=true;const {data,error:e}=await supabase.from('site_feature_configs').select('*').order('sort_order');if(e)error.value=e.message;else rows.value=data||[];loading.value=false}
async function save(row){saving.value=row.feature_key;error.value='';success.value='';const {data,error:e}=await supabase.rpc('update_site_feature_config',{p_feature_key:row.feature_key,p_enabled:row.feature_key==='home'?true:row.enabled,p_sort_order:Number(row.sort_order),p_maintenance_message:row.maintenance_message});saving.value='';if(e){error.value=e.message;return}Object.assign(row,data);success.value=`“${row.display_name}”已更新，前台最多 5 分钟内生效。`}
onMounted(load)
</script>
<template><div class="page"><div class="page-head"><div><h2>前台功能开关</h2><p>统一控制导航、首页入口和直接路由访问。</p></div></div><div v-if="error" class="notice">{{error}}</div><div v-if="success" class="notice" style="background:#eaf5eb;color:#28643a">{{success}}</div><section class="card"><div v-if="loading" class="loading">正在读取配置…</div><div v-else class="table-wrap"><table class="data-table"><thead><tr><th>模块</th><th>状态</th><th>排序</th><th>关闭提示</th><th></th></tr></thead><tbody><tr v-for="row in rows" :key="row.feature_key"><td><b>{{row.display_name}}</b><small>{{row.feature_key}}</small></td><td><button :class="['toggle',{on:row.enabled}]" :disabled="row.feature_key==='home'" @click="row.enabled=!row.enabled" :aria-label="`${row.display_name}${row.enabled?'已开启':'已关闭'}`"></button></td><td><input v-model.number="row.sort_order" type="number" min="0" max="1000" style="width:75px"></td><td><input v-model="row.maintenance_message" maxlength="300" placeholder="关闭后展示的说明" style="width:min(360px,100%)"></td><td><button class="btn secondary" :disabled="saving===row.feature_key" @click="save(row)">{{saving===row.feature_key?'保存中':'保存'}}</button></td></tr></tbody></table></div></section></div></template>
